// Some portions generated by Claude
import { rmSync } from "node:fs";
import { fileURLToPath } from "node:url";
import react from "@vitejs/plugin-react";
import { defineConfig, type Plugin } from "vite";

/**
 * Builds the React graph explorer island into target/frontend, next to the classic scripts emitted by
 * tsconfig.classic.json. Maven adds target/frontend to the WAR as a web resource, so the published paths are
 * /rdf4j-workbench/scripts/graph-explorer/graph-explorer.mjs and /rdf4j-workbench/styles/graph-explorer.css.
 *
 * `npm run dev` serves src/main/frontend/dev/index.html and proxies the Workbench and Server to a locally running
 * server-boot (mvn -pl tools/server-boot spring-boot:run) so the island can be developed against real data.
 */
const frontendRoot = fileURLToPath(new URL("./src/main/frontend", import.meta.url));
const outDir = fileURLToPath(new URL("./target/frontend", import.meta.url));

/**
 * target/frontend is shared with the classic tsc output, so Vite must not empty it (emptyOutDir: false). Instead the
 * explorer's own output (hashed chunks and workers accumulate otherwise) is removed before every build.
 */
let explorerOutputCleaned = false;
function cleanExplorerOutput(): Plugin {
  return {
    name: "rdf4j-clean-explorer-output",
    apply: "build",
    buildStart() {
      // Worker bundles are separate builds that share this plugin: clean once per process, before the first build.
      if (explorerOutputCleaned) {
        return;
      }
      explorerOutputCleaned = true;
      for (const stale of ["scripts/graph-explorer", "styles/graph-explorer.css"]) {
        rmSync(fileURLToPath(new URL(`./target/frontend/${stale}`, import.meta.url)), { recursive: true, force: true });
      }
    },
  };
}

export default defineConfig({
  root: frontendRoot,
  base: "./",
  plugins: [cleanExplorerOutput(), react()],
  build: {
    outDir,
    emptyOutDir: false,
    sourcemap: true,
    cssCodeSplit: false,
    rollupOptions: {
      input: fileURLToPath(new URL("./src/main/frontend/graph-explorer/main.tsx", import.meta.url)),
      output: {
        format: "es",
        entryFileNames: "scripts/graph-explorer/graph-explorer.mjs",
        chunkFileNames: "scripts/graph-explorer/chunks/[name]-[hash].mjs",
        assetFileNames: (asset) =>
          asset.names?.some((name) => name.endsWith(".css"))
            ? "styles/graph-explorer.css"
            : "scripts/graph-explorer/assets/[name]-[hash][extname]",
      },
    },
  },
  worker: {
    format: "es",
    rollupOptions: {
      output: {
        entryFileNames: "scripts/graph-explorer/workers/[name]-[hash].mjs",
        chunkFileNames: "scripts/graph-explorer/workers/[name]-[hash].mjs",
      },
    },
  },
  server: {
    port: 5173,
    strictPort: true,
    open: "/dev/index.html",
    proxy: {
      "/rdf4j-workbench": "http://127.0.0.1:8080",
      "/rdf4j-server": "http://127.0.0.1:8080",
    },
  },
});
